"""Ghi phiên bản môi trường thật vào docs/environment.md — đo, không ghi tay."""

import platform
import sys
from pathlib import Path

OUT = Path(__file__).resolve().parent.parent / "docs" / "environment.md"


def main() -> None:
    for stream in (sys.stdout, sys.stderr):
        if hasattr(stream, "reconfigure"):
            stream.reconfigure(encoding="utf-8", errors="replace")

    import cv2
    import numpy
    import PIL
    import sqlalchemy
    import yaml

    lines = [
        "# Environment — generated by scripts/verify_env.py",
        "",
        f"- OS: {platform.system()} {platform.release()}",
        f"- Python: {platform.python_version()}",
        f"- opencv-python: {cv2.__version__} (SIFT: {'yes' if hasattr(cv2, 'SIFT_create') else 'NO'})",
        f"- numpy: {numpy.__version__}",
        f"- Pillow: {PIL.__version__}",
        f"- SQLAlchemy: {sqlalchemy.__version__}",
        f"- PyYAML: {yaml.__version__}",
    ]
    try:
        import PySide6

        lines.append(f"- PySide6: {PySide6.__version__}")
    except ImportError:
        lines.append("- PySide6: NOT INSTALLED")

    OUT.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print("\n".join(lines))


if __name__ == "__main__":
    main()
